"""Attack on noisy-crc: CRC16(key,P) = key*x^16 mod P over GF(2) is linear in key bits.
Each oracle reply holds the true CRC among 3 candidates -> solve GF(2) system with
unknowns = 512 key bits + 3 selector bits per query, plus per-query sum(sel)=1.
"""
import re, sys, random, socket
from hashlib import sha256
from Crypto.Util.number import long_to_bytes
from Crypto.Cipher import AES

PROMPT = b"Give me your generator polynomial: "


def getCRC16(msg, gen_poly):
    msglen = msg.bit_length()
    msg <<= 16
    for i in range(msglen - 1, -1, -1):
        if (msg >> (i + 16)) & 1:
            msg ^= (gen_poly << i)
    return msg


def basis_cols(gen_poly, nbits=512):
    """cols[k] = getCRC16(1<<k, gen_poly) = x^(16+k) mod P."""
    low = gen_poly & 0xffff
    t = low  # x^16 mod P since x^16 = P xor low
    cols = []
    for _ in range(nbits):
        cols.append(t)
        t = ((t << 1) & 0xffff) ^ (low if (t & 0x8000) else 0)
    return cols


def crc_from_cols(cols, key):
    r = 0
    k = 0
    while key:
        if key & 1:
            r ^= cols[k]
        key >>= 1
        k += 1
    return r


def build_rows(queries, nbits=512):
    N = len(queries)
    U = nbits + 3 * N
    rows = []
    for i, (P, vals) in enumerate(queries):
        cols = basis_cols(P, nbits)
        base = nbits + 3 * i
        # equation rows for each of 16 CRC bits: M_i key + S_i sel = 0
        for b in range(16):
            row = 0
            for k in range(nbits):
                if (cols[k] >> b) & 1:
                    row |= 1 << k
            for j in range(3):
                if (vals[j] >> b) & 1:
                    row |= 1 << (base + j)
            rows.append(row)  # RHS bit (bit U) = 0
        # exactly one selector: sum sel = 1
        rows.append((1 << base) | (1 << (base + 1)) | (1 << (base + 2)) | (1 << U))
    return U, rows


def solve_gf2(U, rows):
    """Return (rank, particular solution int) or None if inconsistent."""
    pivots = {}
    mask = (1 << U) - 1
    for row in rows:
        cur = row
        while True:
            coeff = cur & mask
            if coeff == 0:
                if (cur >> U) & 1:
                    return None
                break
            p = coeff.bit_length() - 1
            if p in pivots:
                cur ^= pivots[p]
            else:
                pivots[p] = cur
                break
    sol = 0
    for p in sorted(pivots):
        row = pivots[p]
        val = (row >> U) & 1
        lowmask = row & ((1 << p) - 1)
        val ^= bin(lowmask & sol).count("1") & 1
        if val:
            sol |= 1 << p
    return len(pivots), sol


def recover(queries, nbits=512):
    U, rows = build_rows(queries, nbits)
    res = solve_gf2(U, rows)
    if res is None:
        return None, "inconsistent"
    rank, sol = res
    key = sol & ((1 << nbits) - 1)
    # verify against every query
    for P, vals in queries:
        if getCRC16(key, P) not in vals:
            return None, "verify-fail rank=%d/%d" % (rank, U)
    return key, "rank=%d/%d" % (rank, U)


def decrypt_flag(enc, key):
    aeskey = sha256(long_to_bytes(key)).digest()[:16]
    return AES.new(aeskey, AES.MODE_CTR, nonce=b"12345678").decrypt(enc)


def recv_until(s, marker):
    buf = b""
    while marker not in buf:
        chunk = s.recv(65536)
        if not chunk:
            break
        buf += chunk
    return buf


def live_solve(nqueries=48, seed=None):
    rnd = random.Random(seed)
    s = socket.create_connection(("noisy-crc", 9999), timeout=30)
    buf = recv_until(s, PROMPT)
    m = re.search(rb"Encrypted flag:\s*([0-9a-fA-F]+)", buf)
    if not m:
        raise RuntimeError("no encrypted flag in banner: %r" % buf[:300])
    enc = bytes.fromhex(m.group(1).decode())
    print("enc flag:", enc.hex())

    used, queries = set(), []
    for _ in range(nqueries):
        while True:
            P = rnd.randint(65537, 131071)
            if P not in used:
                break
        used.add(P)
        s.sendall(str(P).encode() + b"\n")
        buf = recv_until(s, PROMPT)
        m = re.search(rb"\[(\d+),\s*(\d+),\s*(\d+)\]", buf)
        if not m:
            raise RuntimeError("bad reply to poly %d: %r" % (P, buf[-300:]))
        vals = [int(x) for x in m.groups()]
        queries.append((P, vals))
        if len(queries) % 8 == 0:
            key, info = recover(queries)
            print("queries=%d %s" % (len(queries), info))
            if key is not None:
                print("KEY:", hex(key))
                flag = decrypt_flag(enc, key)
                print("FLAG:", flag)
                return flag, enc, key
    key, info = recover(queries)
    print("final:", info)
    if key is None:
        return None, enc, None
    print("KEY:", hex(key))
    flag = decrypt_flag(enc, key)
    print("FLAG:", flag)
    return flag, enc, key


def local_test(trials=20, N=40):
    import secrets
    ok = 0
    for t in range(trials):
        key = secrets.randbits(512)
        queries = []
        for _ in range(N):
            P = random.randint(65537, 131071)
            true = getCRC16(key, P)
            res = [secrets.randbits(16) for _ in range(3)]
            res[secrets.randbelow(3)] = true
            queries.append((P, res))
        rec_key, info = recover(queries)
        good = rec_key == key
        ok += good
        if not good:
            print("trial %d FAIL %s" % (t, info))
        else:
            if t < 2:
                print("trial %d ok %s" % (t, info))
    print("local success %d/%d (N=%d)" % (ok, trials, N))


if __name__ == "__main__":
    if len(sys.argv) > 1 and sys.argv[1] == "local":
        N = int(sys.argv[2]) if len(sys.argv) > 2 else 40
        local_test(20, N)
    else:
        live_solve(int(sys.argv[1]) if len(sys.argv) > 1 else 48)
