from Crypto.Cipher import AES
from Crypto.Util.number import long_to_bytes
from hashlib import sha256

# ---------------- exact copies from chall.py ----------------
def getCRC16(msg, gen_poly):
	assert (1 << 16) <= gen_poly < (1 << 17)  # check if deg = 16
	msglen = msg.bit_length()

	msg <<= 16
	for i in range(msglen - 1, -1, -1):
		if (msg >> (i + 16)) & 1:
			msg ^= (gen_poly << i)

	return msg

def oracle(secret, gen_poly, rnd=secrets):
	res = [rnd.randbits(16) for _ in range(3)]
	res[rnd.randbelow(3)] = getCRC16(secret, gen_poly)
	return res
# ------------------------------------------------------------

def columns(P):
	"""cols[k] = x^(k+16) mod P == getCRC16(1<<k, P), via shift/reduce recurrence."""
	r = P ^ (1 << 16)          # x^16 mod P  (deg P == 16)
	cols = []
	for _k in range(512):
		cols.append(r)
		r <<= 1
		if (r >> 16) & 1:
			r ^= P
	return cols

def predict(key, cols):
	acc, k = 0, 0
	while key:
		if key & 1:
			acc ^= cols[k]
		key >>= 1
		k += 1
	return acc

def popcount(x):
	return bin(x).count('1')

def solve_gf2(rows, U):
	"""rows: list of ints; bit U is augmented RHS. Returns (rank, sol or None)."""
	piv = {}          # col -> row
	for r in rows:
		cur = r
		while True:
			low = cur & -cur
			if low == 0:
				break
			c = low.bit_length() - 1
			if c >= U:               # 0 == 1 -> inconsistent
				return None, None
			if c in piv:
				cur ^= piv[c]
			else:
				piv[c] = cur
				break
	# full RREF
	for c in sorted(piv):
		row = piv[c]
		bit = 1 << c
		for c2 in piv:
			if c2 != c and (piv[c2] & bit):
				piv[c2] ^= row
	sol = 0
	for c in sorted(piv):
		if (piv[c] >> U) & 1:
			sol |= (1 << c)
	free = [f for f in range(U) if f not in piv]
	null = []
	for f in free:
		v = 1 << f
		for c in piv:
			if (piv[c] >> f) & 1:
				v |= 1 << c
		null.append(v)
	return len(piv), (sol, null)

def build_rows(polys, responses, U):
	rows = []
	for i, (P, res) in enumerate(zip(polys, responses)):
		cols = columns(P)
		keypart = [0]*16
		for k in range(512):
			c = cols[k]
			while c:
				b = c & -c
				keypart[b.bit_length()-1] |= (1 << k)
				c ^= b
		base = 512 + 3*i
		for j in range(16):
			row = keypart[j]
			for s in range(3):
				if (res[s] >> j) & 1:
					row |= 1 << (base + s)
			rows.append(row)                       # .. = 0
		rows.append((1 << base) | (1 << (base+1)) | (1 << (base+2)) | (1 << U))  # sum sel = 1
	return rows

FLAG_RE = re.compile(rb'[A-Za-z0-9_]*\{[ -~]{5,60}\}')

def trial(key, N, poly_mode='odd', rnd=secrets, verbose=False):
	polys, responses, used = [], [], set()
	while len(polys) < N:
		P = rnd.randrange(1 << 16, 1 << 17)
		if poly_mode == 'odd' and not (P & 1):
			continue
		if P in used:
			continue
		used.add(P)
		polys.append(P)
		responses.append(oracle(key, P, rnd))
	U = 512 + 3*N
	rows = build_rows(polys, responses, U)
	rank, out = solve_gf2(rows, U)
	if rank is None:
		return dict(ok=False, reason='inconsistent', rank=None, U=U, nullity=None,
		            key_amb=False)
	sol, null = out
	nullity = U - rank
	keypart_amb = any(v & ((1 << 512) - 1) for v in null)
	rec = sol & ((1 << 512) - 1)
	ok = (rec == key)
	# independent self-check of the recovered key against the oracle data
	consistent = all(getCRC16(rec, P) in res for P, res in zip(polys, responses))
	return dict(ok=ok, rank=rank, U=U, nullity=nullity, key_amb=keypart_amb,
	            consistent=consistent, rec=rec, reason='ok')

def selfcheck():
	"""validate linearity, columns, and reference agreement incl. edge cases."""
	rnd = random.Random(1234)
	ok = True
	# 1) linearity + column table agreement, random polys (odd and even const term)
	for _ in range(20):
		P = rnd.randrange(1 << 16, 1 << 17)
		cols = columns(P)
		for k in [0, 1, 7, 63, 255, 511]:
			if getCRC16(1 << k, P) != cols[k]:
				ok = False; print('COL MISMATCH', hex(P), k)
		for _ in range(5):
			a = rnd.getrandbits(512); b = rnd.getrandbits(512)
			if getCRC16(a ^ b, P) != (getCRC16(a, P) ^ getCRC16(b, P)):
				ok = False; print('NOT LINEAR', hex(P))
			if getCRC16(a, P) != predict(a, cols):
				ok = False; print('PREDICT MISMATCH', hex(P), a)
	# 2) key values with small bit_length (leading zeros) and full 512 bits
	for bl in [1, 2, 16, 17, 300, 511, 512]:
		P = rnd.randrange(1 << 16, 1 << 17) | 1
		cols = columns(P)
		k = rnd.getrandbits(bl) | (1 << (bl-1))
		if getCRC16(k, P) != predict(k, cols):
			ok = False; print('EDGE KEY MISMATCH', bl)
	# 3) reduction really equals mod over GF(2) (independent implementation)
	def polymod(a, p):
		dp = p.bit_length() - 1
		while a.bit_length() - 1 >= dp and a:
			a ^= p << (a.bit_length() - 1 - dp)
		return a
	for _ in range(50):
		P = rnd.randrange(1 << 16, 1 << 17)
		k = rnd.getrandbits(512)
		if getCRC16(k, P) != polymod(k << 16, P):
			ok = False; print('MOD MISMATCH', hex(P))
	# 4) rank of the key->CRC map for odd vs even constant term
	r = rnd.randrange(1 << 16, 1 << 17) | 1
	cols = columns(r)
	span = set()
	for k in range(512):
		span.add(cols[k])
	d = 0
	basis = []
	for v in cols:
		x = v
		for bb in basis:
			x = min(x, x ^ bb)
		if x:
			basis.append(x); basis.sort(reverse=True); d += 1
	print('rank of key->CRC map (odd const term) =', d)
	r2 = rnd.randrange(1 << 15, 1 << 16) << 1
	cols2 = columns(r2); basis = []; d2 = 0
	for v in cols2:
		x = v
		for bb in basis:
			x = min(x, x ^ bb)
		if x:
			basis.append(x); basis.sort(reverse=True); d2 += 1
	print('rank of key->CRC map (even const term, x|P) =', d2)
	print('SELFCHECK', 'PASS' if ok else 'FAIL')
	return ok

def enc_flag(key, flag):
	cipher = AES.new(sha256(long_to_bytes(key)).digest()[:16], AES.MODE_CTR, nonce=b"12345678")
	return cipher.encrypt(flag)

if __name__ == '__main__':
	selfcheck()
	FLAG = b'flag{local_simulator_placeholder}'
	rnd = random.Random(2024)
	for N in [25, 30, 35, 36, 37, 38, 40, 45, 50]:
		succ = 0; trials = 20; ranks = []; nulls = []; ambiguities = 0; inconsistent = 0
		for t in range(trials):
			key = rnd.getrandbits(512)
			r = trial(key, N, 'odd', rnd)
			if r.get('reason') == 'inconsistent':
				inconsistent += 1
				continue
			ranks.append(r['rank']); nulls.append(r['nullity'])
			if r['ok'] and r['consistent']:
				succ += 1
			if r['key_amb']:
				ambiguities += 1
		print(f'N={N:3d} U={512+3*N:4d} rows={17*N:4d} success={succ}/{trials} '
		      f'rank[min,max]=[{min(ranks)},{max(ranks)}] nullity[min,max]=[{min(nulls)},{max(nulls)}] '
		      f'key-ambiguity-trials={ambiguities} inconsistent={inconsistent}')
"}

