def crc16(msg, gen_poly):
    """Exact copy of chall.py getCRC16 (bit-level text otherwise identical)."""
    assert (1 << 16) <= gen_poly < (1 << 17)
    msglen = msg.bit_length()
    msg <<= 16
    for i in range(msglen - 1, -1, -1):
        if (msg >> (i + 16)) & 1:
            msg ^= (gen_poly << i)
    return msg


def polymod(a, m):
    """a mod m over GF(2), m != 0."""
    dm = m.bit_length() - 1
    while a and a.bit_length() - 1 >= dm:
        a ^= m << (a.bit_length() - 1 - dm)
    return a


def polymul(a, b):
    r = 0
    while b:
        if b & 1:
            r ^= a
        a <<= 1
        b >>= 1
    return r


def polygcd(a, b):
    while b:
        a, b = b, polymod(a, b)
    return a


def enumerate_irreducibles(dmax):
    """All monic irreducible polys over GF(2) of degree 1..dmax with nonzero
    constant term (x itself is excluded because we need gcd(G, x) = 1)."""
    irr = []
    by_deg = {}
    for d in range(1, dmax + 1):
        found = []
        for p in range((1 << d) | 1, 1 << (d + 1), 2):
            ok = True
            for q in irr:
                if (q.bit_length() - 1) * 2 > d:
                    break
                if polymod(p, q) == 0:
                    ok = False
                    break
            if ok:
                found.append(p)
        irr.extend(found)
        by_deg[d] = found
    return irr, by_deg


def factor(p, irreducibles):
    """irreducible factorisation of p -> list of irreducible factors (with mult)."""
    out = []
    for q in irreducibles:
        if q.bit_length() - 1 > p.bit_length() - 1:
            break
        while polymod(p, q) == 0:
            out.append(q)
            p //= 1  # no integer division of polys; use exact poly division below
            break
        # redo properly
    return out


def polydiv(a, b):
    """exact quotient+remainder of a by b over GF(2)"""
    db = b.bit_length() - 1
    q = 0
    while a and a.bit_length() - 1 >= db:
        s = a.bit_length() - 1 - db
        q ^= 1 << s
        a ^= b << s
    return q, a


def factorize(p, irreducibles):
    """full irreducible factorisation (with multiplicity) of p."""
    fs = []
    for q in irreducibles:
        dq = q.bit_length() - 1
        if dq > p.bit_length() - 1:
            break
        while p and dq <= p.bit_length() - 1 and polymod(p, q) == 0:
            fs.append(q)
            p, r = polydiv(p, q)
            assert r == 0
    assert p == 1, (p, fs)
    return fs


def candidates(d):
    """all monic degree-d polys over GF(2) with constant term 1."""
    return [p for p in range((1 << d) | 1, 1 << (d + 1), 2)]


def distinct_irr_capacity(d, irr):
    """total degree of all irreducibles of degree <= d (x excluded)."""
    return sum(q.bit_length() - 1 for q in irr if q.bit_length() - 1 <= d)
