            continue
        used.add(P); out.append(P)
    return out


def key_only_rank(polys):
    """rank of delta -> (CRC(delta,P_1),...,CRC(delta,P_N)) : gives how many queries
    are needed if the true CRC were unambiguous (lcm degree capped at 512)."""
    piv = {}
    for P in polys:
        cols = columns(P)
        for j in range(16):
            row = 0
            for k in range(512):
                if (cols[k] >> j) & 1:
                    row |= 1 << k
            cur = row
            while cur:
                c = cur.bit_length() - 1
                if c in piv:
                    cur ^= piv[c]
                else:
                    piv[c] = cur
                    break
    return len(piv)


def full_run(key, polys, rnd):
    resp = [oracle(key, P, RR(rnd)) for P in polys]
    N = len(polys); U = 512 + 3 * N
    rank, out = solve_gf2(build_rows(polys, resp, U), U)
    if rank is None:
        return None
    sol, null = out
    rec = sol & ((1 << 512) - 1)
    return dict(rank=rank, U=U, nullity=U - rank, ok=(rec == key),
                consistent=all(getCRC16(rec, P) in r for P, r in zip(polys, resp)),
                key_amb=any(v & ((1 << 512) - 1) for v in null))


